"use strict";(globalThis.webpackChunkdoqumentation=globalThis.webpackChunkdoqumentation||[]).push([[8381],{49557(e,s,n){n.r(s),n.d(s,{assets:()=>o,contentTitle:()=>a,default:()=>d,frontMatter:()=>r,metadata:()=>i,toc:()=>l});const i=JSON.parse('{"id":"learning/courses/quantum-computing-in-practice/introduction","title":"Introduction","description":"Un cours IBM gratuit sur l\'informatique quantique \xe0 l\'\xe9chelle utilitaire, avec des cas d\'usage r\xe9alistes et les meilleures pratiques","source":"@site/i18n/fr/docusaurus-plugin-content-docs/current/learning/courses/quantum-computing-in-practice/introduction.mdx","sourceDirName":"learning/courses/quantum-computing-in-practice","slug":"/learning/courses/quantum-computing-in-practice/introduction","permalink":"/learning/courses/quantum-computing-in-practice/introduction","draft":false,"unlisted":false,"editUrl":"https://github.com/JanLahmann/doQumentation/tree/main/docs/learning/courses/quantum-computing-in-practice/introduction.mdx","tags":[],"version":"current","frontMatter":{"title":"Introduction","sidebar_label":"Introduction","description":"Un cours IBM gratuit sur l\'informatique quantique \xe0 l\'\xe9chelle utilitaire, avec des cas d\'usage r\xe9alistes et les meilleures pratiques","notebook_path":"learning/courses/quantum-computing-in-practice/introduction.ipynb"},"sidebar":"tutorialsSidebar","previous":{"title":"Aper\xe7u","permalink":"/learning/courses/quantum-computing-in-practice/"},"next":{"title":"Ex\xe9cuter des circuits quantiques","permalink":"/learning/courses/quantum-computing-in-practice/running-quantum-circuits"}}');var t=n(74848),u=n(28453);const r={title:"Introduction",sidebar_label:"Introduction",description:"Un cours IBM gratuit sur l'informatique quantique \xe0 l'\xe9chelle utilitaire, avec des cas d'usage r\xe9alistes et les meilleures pratiques",notebook_path:"learning/courses/quantum-computing-in-practice/introduction.ipynb"},a="Introduction au cours {#course-introduction}",o={},l=[{value:"\xc0 propos de ce cours",id:"about-this-course",level:2},{value:"Utilit\xe9 quantique",id:"quantum-utility",level:3},{value:"Simuler la Nature",id:"simulating-nature",level:3},{value:"Un focus sur les processeurs quantiques plus grands",id:"a-focus-on-larger-quantum-processors",level:3},{value:"Public vis\xe9 et objectifs du cours",id:"audience-and-course-goals",level:3},{value:"L&#39;histoire du calcul",id:"the-story-of-computation",level:2},{value:"Les dispositifs de calcul depuis l&#39;Antiquit\xe9",id:"computing-devices-since-ancient-times",level:3},{value:"Liens avec le monde physique",id:"connections-to-the-physical-world",level:3},{value:"La loi de Moore",id:"moores-law",level:3},{value:"L&#39;informatique quantique",id:"quantum-computing",level:2},{value:"La m\xe9canique quantique et le calcul",id:"quantum-mechanics-and-computation",level:3},{value:"L&#39;informatique quantique en th\xe9orie",id:"quantum-computing-in-theory",level:3},{value:"L&#39;informatique quantique en pratique",id:"quantum-computing-in-practice",level:3},{value:"Applications potentielles",id:"potential-applications",level:3},{value:"\xc9tat de la technologie",id:"state-of-the-technology",level:3},{value:"Conclusion",id:"conclusion",level:2}];function c(e){const s={a:"a",em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",p:"p",strong:"strong",ul:"ul",...(0,u.R)(),...e.components},{IBMVideo:n}=s;return n||function(e,s){throw new Error("Expected "+(s?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("IBMVideo",!0),(0,t.jsxs)(t.Fragment,{children:["\n",(0,t.jsx)(s.header,{children:(0,t.jsx)(s.h1,{id:"course-introduction",children:"Introduction au cours"})}),"\n",(0,t.jsxs)(s.p,{children:["Avant de commencer, merci de remplir ce court ",(0,t.jsx)(s.a,{href:"https://your.feedback.ibm.com/jfe/form/SV_6PadhMQiGWsxXTM",children:"sondage pr\xe9-cours"}),", qui nous aide \xe0 am\xe9liorer nos contenus et l'exp\xe9rience utilisateur."]}),"\n",(0,t.jsxs)(s.p,{children:["Clique ci-dessous pour \xe9couter l'introduction au cours par Olivia Lanes, ou ouvre la vid\xe9o dans une fen\xeatre s\xe9par\xe9e sur ",(0,t.jsx)(s.a,{href:"https://youtube.com/watch?v=sVRpKhCfKRI",children:"YouTube."})]}),"\n",(0,t.jsx)(n,{id:"134063425",title:"Dans cette vid\xe9o, Olivia Lanes donne un aper\xe7u de l'informatique quantique pratique \xe0 l'\xe8re de l'utilit\xe9. Elle pr\xe9sente le public vis\xe9 et donne quelques notions de fond sur des sujets comme la loi de Moore et les fondements th\xe9oriques de l'informatique quantique."}),"\n",(0,t.jsx)(s.h2,{id:"about-this-course",children:"\xc0 propos de ce cours"}),"\n",(0,t.jsxs)(s.p,{children:["Bienvenue dans ",(0,t.jsx)(s.em,{children:"Quantum Computing in Practice"})," \u2014 un cours centr\xe9 sur les ordinateurs quantiques d'aujourd'hui et sur la fa\xe7on de les exploiter au maximum.\nIl couvre des cas d'usage potentiels et r\xe9alistes pour l'informatique quantique, ainsi que les meilleures pratiques pour faire tourner des exp\xe9riences sur des processeurs quantiques de 100 qubits ou plus."]}),"\n",(0,t.jsx)(s.h3,{id:"quantum-utility",children:"Utilit\xe9 quantique"}),"\n",(0,t.jsxs)(s.p,{children:["C'est une \xe9poque passionnante pour l'informatique quantique.\nApr\xe8s des ann\xe9es de recherche et de d\xe9veloppement th\xe9oriques et exp\xe9rimentaux, les ordinateurs quantiques approchent d'un point o\xf9 ils commencent \xe0 rivaliser avec les ordinateurs classiques et \xe0 d\xe9montrer une ",(0,t.jsx)(s.em,{children:"utilit\xe9"}),"."]}),"\n",(0,t.jsxs)(s.p,{children:["L'utilit\xe9 n'est pas la m\xeame chose que l'",(0,t.jsx)(s.em,{children:"avantage quantique"}),", qui d\xe9signe la capacit\xe9 des ordinateurs quantiques \xe0 ",(0,t.jsx)(s.em,{children:"surpasser"})," les ordinateurs classiques sur des t\xe2ches significatives.\nLes ordinateurs classiques disposent d'une puissance et d'une adaptabilit\xe9 incroyables, et la r\xe9alit\xe9 est que les ordinateurs quantiques ne sont tout simplement pas encore capables de les battre.\nOn a vu des d\xe9cennies d'avanc\xe9es en calcul classique \u2014 non seulement dans le mat\xe9riel, mais aussi dans les algorithmes \u2014 et il est clair que la technologie du calcul num\xe9rique \xe9lectronique a radicalement transform\xe9 notre monde."]}),"\n",(0,t.jsxs)(s.p,{children:["L'informatique quantique, en revanche, se trouve \xe0 un stade diff\xe9rent de son d\xe9veloppement.\nElle impose des exigences extr\xeames sur notre contr\xf4le des syst\xe8mes m\xe9caniques quantiques et repousse les limites de la technologie actuelle \u2014 on ne peut pas raisonnablement s'attendre \xe0 ma\xeetriser cette nouvelle technologie et battre le calcul classique d\xe8s le d\xe9part.\nMais on voit des signes qui sugg\xe8rent que les ordinateurs quantiques commencent \xe0 devenir comp\xe9titifs avec les m\xe9thodes classiques pour certaines t\xe2ches, ce qui est une \xe9tape naturelle dans l'\xe9volution technologique de l'informatique quantique, connue sous le nom d'",(0,t.jsx)(s.em,{children:"utilit\xe9 quantique"}),"."]}),"\n",(0,t.jsx)(s.p,{children:"\xc0 mesure que la technologie progresse et que de nouvelles m\xe9thodes de calcul quantique sont d\xe9velopp\xe9es, on peut raisonnablement s'attendre \xe0 ce que ses avantages deviennent de plus en plus marqu\xe9s \u2014 mais cela prendra du temps.\nAu fil de cette \xe9volution, on observera vraisemblablement un dialogue en va-et-vient avec le calcul classique :\ndes d\xe9monstrations de calcul quantique seront r\xe9alis\xe9es, le calcul classique r\xe9pondra, le calcul quantique passera \xe0 une autre it\xe9ration, et le sch\xe9ma se r\xe9p\xe9tera.\nEt un jour, quand la performance d'un ordinateur quantique ne pourra plus \xeatre \xe9gal\xe9e classiquement, on formulera l'hypoth\xe8se d'avoir observ\xe9 un avantage quantique \u2014 mais m\xeame alors, on ne sera pas certains !\nProuver des r\xe9sultats d'impossibilit\xe9 pour les ordinateurs classiques est lui-m\xeame un probl\xe8me d'une difficult\xe9 insurmontable, pour autant qu'on le sache."}),"\n",(0,t.jsx)(s.h3,{id:"simulating-nature",children:"Simuler la Nature"}),"\n",(0,t.jsx)(s.p,{children:"Les simulateurs classiques \u2014 c'est-\xe0-dire des programmes informatiques fonctionnant sur des ordinateurs classiques qui simulent des syst\xe8mes physiques \u2014 peuvent faire des pr\xe9dictions sur les syst\xe8mes m\xe9caniques quantiques.\nMais les simulateurs classiques ne sont pas quantiques et ne peuvent pas \xe9muler directement les syst\xe8mes quantiques.\nIls utilisent \xe0 la place des calculs math\xe9matiques pour approximer le comportement quantique.\n\xc0 mesure que la taille des syst\xe8mes simul\xe9s augmente, la charge n\xe9cessaire pour le faire cro\xeet de fa\xe7on dramatique, ce qui limite les syst\xe8mes quantiques qui peuvent \xeatre simul\xe9s classiquement, la dur\xe9e des simulations et la pr\xe9cision des r\xe9sultats."}),"\n",(0,t.jsx)(s.p,{children:"Les ordinateurs quantiques, en revanche, peuvent \xe9muler les syst\xe8mes quantiques de mani\xe8re plus directe \u2014 et par cons\xe9quent, la charge qu'ils requi\xe8rent \xe9volue bien mieux \xe0 mesure que la taille du syst\xe8me cro\xeet.\nC'est pr\xe9cis\xe9ment cette id\xe9e que Richard Feynman avait dans les ann\xe9es 1980, et qui a motiv\xe9 les premi\xe8res investigations sur le potentiel des ordinateurs quantiques.\nOn reviendra l\xe0-dessus plus tard !"}),"\n",(0,t.jsx)(s.p,{children:"Des chercheurs d'IBM\xae ont publi\xe9 un article en 2023 montrant, pour la premi\xe8re fois, qu'un ordinateur quantique peut rivaliser avec les techniques classiques les plus avanc\xe9es pour simuler un mod\xe8le physique particulier.\nSes r\xe9sultats peuvent encore \xeatre \xe9gal\xe9s par des techniques avanc\xe9es tournant sur des ordinateurs classiques \u2014 mais il a surpass\xe9 les algorithmes par force brute,\net il offre aussi un nouveau point de donn\xe9es auquel diff\xe9rentes m\xe9thodes de simulation (qui ne sont pas exactes et ne donnent pas toutes les m\xeames pr\xe9dictions) peuvent \xeatre compar\xe9es."}),"\n",(0,t.jsx)(s.h3,{id:"a-focus-on-larger-quantum-processors",children:"Un focus sur les processeurs quantiques plus grands"}),"\n",(0,t.jsx)(s.p,{children:"Les utilisateurs qui ont d\xe9j\xe0 utilis\xe9 du mat\xe9riel quantique IBM ont peut-\xeatre remarqu\xe9 que les processeurs plus petits que nous mettions auparavant \xe0 disposition du public ont \xe9t\xe9 mis hors ligne, pour laisser place \xe0 des processeurs plus grands (100+ qubits).\nCes processeurs plus petits pouvaient facilement \xeatre simul\xe9s classiquement.\nAinsi, m\xeame s'ils repr\xe9sentaient des \xe9tapes interm\xe9diaires accessibles au public dans une technologie en progression, ils ne pouvaient pas d\xe9montrer d'utilit\xe9 quantique : tout ce qu'on pouvait faire avec eux pouvait tout aussi facilement \xeatre r\xe9alis\xe9 avec une simulation classique."}),"\n",(0,t.jsxs)(s.p,{children:["\xc0 environ 100 qubits, cependant, ce n'est plus le cas ; les processeurs quantiques de cette taille ne peuvent plus \xeatre simul\xe9s classiquement.\nCela repr\xe9sente une sorte de transition de phase, vers une nouvelle \xe8re de la technologie de calcul quantique o\xf9 le ",(0,t.jsx)(s.em,{children:"potentiel"})," de surpasser le calcul classique existe.\nC'est l\xe0 qu'IBM a choisi de se concentrer \u2014 chercher la puissance computationnelle quantique et viser un avantage quantique \xe0 terme."]}),"\n",(0,t.jsx)(s.p,{children:"Nous encourageons nos utilisateurs \xe0 exploiter ces nouveaux dispositifs au maximum, \xe0 les exp\xe9rimenter, \xe0 pousser leurs limites, et \xe0 transmettre les le\xe7ons apprises \xe0 la prochaine g\xe9n\xe9ration de processeurs quantiques en cours de d\xe9veloppement.\nL'objectif de ce cours est de te permettre de faire exactement cela !"}),"\n",(0,t.jsx)(s.h3,{id:"audience-and-course-goals",children:"Public vis\xe9 et objectifs du cours"}),"\n",(0,t.jsx)(s.p,{children:"Ce cours s'adresse \xe0 toute personne souhaitant d\xe9velopper de nouvelles applications pour les ordinateurs quantiques, mettre \xe0 l'\xe9chelle son travail actuel en informatique quantique, ou apprendre \xe0 utiliser des processeurs quantiques dans son flux de travail.\nCela inclut non seulement les physiciens et les informaticiens, mais aussi les ing\xe9nieurs, les chimistes, les scientifiques des mat\xe9riaux, et toute personne int\xe9ress\xe9e \xe0 ma\xeetriser le mat\xe9riel de calcul quantique."}),"\n",(0,t.jsx)(s.p,{children:"Le cours sera pratique et ax\xe9 sur l'utilisation concr\xe8te des ordinateurs quantiques.\nParmi les sujets et comp\xe9tences qu'il aborde :"}),"\n",(0,t.jsxs)(s.ul,{children:["\n",(0,t.jsx)(s.li,{children:"Ex\xe9cuter des t\xe2ches \xe0 l'\xe9chelle utilitaire sur des processeurs quantiques via Qiskit Runtime"}),"\n",(0,t.jsx)(s.li,{children:"Utiliser des techniques d'att\xe9nuation des erreurs pour am\xe9liorer les r\xe9sultats sur le mat\xe9riel"}),"\n",(0,t.jsx)(s.li,{children:"Domaines d'application potentiels pour les ordinateurs quantiques \xe0 court terme"}),"\n"]}),"\n",(0,t.jsxs)(s.p,{children:["Ce cours ne couvre pas la th\xe9orie introductive du calcul quantique, et suppose une familiarit\xe9 de base avec les qubits et les circuits quantiques.\nLe cours ",(0,t.jsx)(s.em,{children:"Bases de l'information quantique"})," sur cette plateforme couvre ce contenu, et est recommand\xe9 en premier pour ceux qui sont nouveaux dans l'informatique quantique."]}),"\n",(0,t.jsx)(s.h2,{id:"the-story-of-computation",children:"L'histoire du calcul"}),"\n",(0,t.jsxs)(s.p,{children:["L'informatique quantique est une nouvelle technologie passionnante \xe0 un stade pr\xe9coce de d\xe9veloppement \u2014 mais ce n'est qu'un chapitre d'une histoire qui remonte \xe0 des mill\xe9naires.\nC'est l'histoire du ",(0,t.jsx)(s.em,{children:"calcul"})," et de ses connections multiples avec le ",(0,t.jsx)(s.em,{children:"monde physique"}),"."]}),"\n",(0,t.jsx)(s.h3,{id:"computing-devices-since-ancient-times",children:"Les dispositifs de calcul depuis l'Antiquit\xe9"}),"\n",(0,t.jsxs)(s.p,{children:["Depuis l'Antiquit\xe9, nous, les humains, avons eu besoin d'effectuer des ",(0,t.jsx)(s.em,{children:"calculs"})," \u2014 autrement dit, de traiter l'information selon certaines r\xe8gles et contraintes \u2014 pour permettre la communication, la construction, le commerce, la science, et d'autres aspects de nos vies.\nNous nous sommes tourn\xe9s vers le monde physique pour obtenir de l'aide, et gr\xe2ce \xe0 des d\xe9couvertes ing\xe9nieuses, nous avons construit des dispositifs pour nous aider \xe0 calculer."]}),"\n",(0,t.jsxs)(s.p,{children:["Il y a longtemps, des dispositifs en bois, en os et en cordes nou\xe9es stockaient des informations et facilitaient les calculs.\nDes dispositifs m\xe9caniques construits \xe0 partir de leviers, d'engrenages et d'autres m\xe9canismes ont \xe9volu\xe9 depuis les premi\xe8res horloges astronomiques, jusqu'aux calculatrices, en passant par des dispositifs de calcul sophistiqu\xe9s comme les analyseurs diff\xe9rentiels qui r\xe9solvaient des \xe9quations \xe0 l'aide de roues et de disques rotatifs.\nM\xeame la technologie de l'\xe9criture a jou\xe9 un r\xf4le important dans cette histoire, en permettant aux ",(0,t.jsx)(s.em,{children:"gens"})," d'effectuer des calculs qu'ils n'auraient pas pu faire autrement."]}),"\n",(0,t.jsx)(s.p,{children:"Quand on pense aux ordinateurs aujourd'hui, on pense g\xe9n\xe9ralement aux ordinateurs num\xe9riques \xe9lectroniques.\nMais il s'agit en fait d'une technologie assez r\xe9cente : les premiers ordinateurs num\xe9riques \xe9lectroniques ont \xe9t\xe9 construits dans les ann\xe9es 1940.\n(En comparaison, l'abaque sum\xe9rien est suppos\xe9 avoir \xe9t\xe9 invent\xe9 entre 2700 et 2300 av. J.-C.)\nLa technologie a consid\xe9rablement progress\xe9 depuis lors et les ordinateurs sont d\xe9sormais omnipr\xe9sents.\nOn les trouve dans les maisons, les lieux de travail, et les v\xe9hicules qui nous transportent entre eux, et beaucoup d'entre nous les emportent partout avec nous."}),"\n",(0,t.jsxs)(s.p,{children:["On dispose aussi de ",(0,t.jsx)(s.em,{children:"supercalculateurs"}),", qui sont de grands ensembles de puissants processeurs classiques interconnect\xe9s en parall\xe8le.\nIls figurent parmi les meilleurs outils que l'humanit\xe9 ait jamais construits pour r\xe9soudre des probl\xe8mes difficiles, et leur puissance et leur fiabilit\xe9 continuent de progresser.\nMais il existe quand m\xeame des probl\xe8mes de calcul importants que m\xeame ces mastodontes ne pourront jamais r\xe9soudre, en raison de la difficult\xe9 computationnelle inh\xe9rente \xe0 ces probl\xe8mes."]}),"\n",(0,t.jsx)(s.h3,{id:"connections-to-the-physical-world",children:"Liens avec le monde physique"}),"\n",(0,t.jsxs)(s.p,{children:["Les ordinateurs ont de nombreux usages.\nUn usage important des ordinateurs est d'",(0,t.jsx)(s.em,{children:"apprendre"})," sur le monde physique et de mieux comprendre ses r\xe9gularit\xe9s.\nLes usages historiques dans cette cat\xe9gorie ont inclus la pr\xe9diction des \xe9clipses et des mar\xe9es, la compr\xe9hension du mouvement des corps astronomiques, et (\xe0 une \xe9poque plus r\xe9cente) la mod\xe9lisation des explosions.\nAujourd'hui, il n'existe gu\xe8re de laboratoire de physique dans le monde sans ordinateur."]}),"\n",(0,t.jsxs)(s.p,{children:["Plus g\xe9n\xe9ralement, la physique et le calcul ont toujours \xe9t\xe9 \xe9troitement li\xe9s.\nLe calcul ne peut pas exister dans le vide : l'information requiert un support, et pour calculer, on doit exploiter le monde physique d'une certaine fa\xe7on.\nRolf Landauer, informaticien (et employ\xe9 d'IBM), a reconnu il y a des d\xe9cennies que l'information est physique, n'existant qu'\xe0 travers une repr\xe9sentation physique.\nLe ",(0,t.jsx)(s.em,{children:"principe de Landauer"})," \xe9tablit un lien entre l'information et les lois de la thermodynamique, mais il en existe en fait beaucoup d'autres."]}),"\n",(0,t.jsx)(s.p,{children:"Comprendre le monde physique est l'objectif de la physique en tant que discipline, mais c'est en r\xe9alit\xe9 une relation \xe0 double sens.\nGr\xe2ce \xe0 notre compr\xe9hension du monde physique, nous pouvons exploiter de nouvelles technologies pour nous aider \xe0 calculer, et \xe0 travers elles, nous continuons \xe0 apprendre sur le monde physique \u2014 en quelque sorte, en tirant la physique et la technologie computationnelle vers le haut par leurs propres bootstraps."}),"\n",(0,t.jsx)(s.h3,{id:"moores-law",children:"La loi de Moore"}),"\n",(0,t.jsx)(s.p,{children:"La loi de Moore est une observation selon laquelle le nombre maximal de transistors dans un circuit int\xe9gr\xe9 double environ tous les 2 ans.\nAu cours des 5 derni\xe8res d\xe9cennies environ, non seulement on a observ\xe9 cette tendance, mais on en a aussi r\xe9colt\xe9 les b\xe9n\xe9fices.\nAvec plus de transistors sur une puce, on peut effectuer des calculs plus complexes et les r\xe9aliser plus rapidement.\nC'est pourquoi les ordinateurs sont devenus de plus en plus puissants au fil du temps."}),"\n",(0,t.jsx)(s.p,{children:"Cependant, la \xab loi \xbb de Moore arrive n\xe9cessairement \xe0 sa fin.\nLes experts ne s'accordent pas sur quand cela se produira, et certains soutiennent que c'est d\xe9j\xe0 le cas.\nMais on sait avec certitude que cela doit in\xe9vitablement arriver, car il existe une limite th\xe9orique \xe0 la miniaturisation des composants informatiques.\nOn ne peut pas fabriquer un transistor plus petit qu'un atome !\nM\xeame si \xe7a peut sembler exag\xe9r\xe9, c'est le mur que nous approchons."}),"\n",(0,t.jsx)(s.p,{children:"La solution n'est pas de capituler en disant : \xab Eh bien, c'est le mieux qu'on puisse faire. \xbb\nCela va \xe0 l'encontre de la nature humaine.\nNous devons plut\xf4t nous tourner vers le monde physique pour trouver de nouveaux outils computationnels, et c'est l\xe0 qu'entre en jeu l'informatique quantique."}),"\n",(0,t.jsx)(s.h2,{id:"quantum-computing",children:"L'informatique quantique"}),"\n",(0,t.jsx)(s.h3,{id:"quantum-mechanics-and-computation",children:"La m\xe9canique quantique et le calcul"}),"\n",(0,t.jsx)(s.p,{children:"La m\xe9canique quantique a \xe9t\xe9 d\xe9couverte au d\xe9but du XXe si\xe8cle, et elle a d\xe9j\xe0 jou\xe9 un r\xf4le important dans le calcul.\nEn effet, notre compr\xe9hension de la m\xe9canique quantique a, en partie, rendu possible les ordinateurs modernes.\nSans la m\xe9canique quantique, par exemple, il est difficile d'imaginer que le disque dur \xe0 semi-conducteurs aurait \xe9t\xe9 invent\xe9."}),"\n",(0,t.jsx)(s.h3,{id:"quantum-computing-in-theory",children:"L'informatique quantique en th\xe9orie"}),"\n",(0,t.jsx)(s.p,{children:"Lorsque Richard Feynman a propos\xe9 pour la premi\xe8re fois la notion d'ordinateur quantique en 1982, son objectif \xe9tait de simuler des syst\xe8mes m\xe9caniques quantiques.\nLes calculs n\xe9cessaires pour y parvenir semblaient trop difficiles pour les ordinateurs ordinaires \u2014 mais peut-\xeatre qu'avec un ordinateur fonctionnant selon une description m\xe9canique quantique du monde, les syst\xe8mes pourraient \xeatre \xe9mul\xe9s directement."}),"\n",(0,t.jsx)(s.p,{children:"C'est aujourd'hui l'une des voies les plus prometteuses de l'informatique quantique.\nD'apr\xe8s notre meilleure compr\xe9hension, la Nature n'est pas classique \u2014 elle est quantique.\nAinsi, les ordinateurs quantiques pourraient \xeatre des outils pr\xe9cieux pour la comprendre.\nLes ordinateurs classiques, en revanche, ne peuvent qu'approximer ce qui se passe r\xe9ellement dans la Nature, et dans certains cas ces\napproximations sont tr\xe8s limit\xe9es."}),"\n",(0,t.jsx)(s.p,{children:"Une fa\xe7on d'y r\xe9fl\xe9chir est \xe0 travers une analogie avec les souffleries.\nLa dynamique des fluides est notoirement difficile \xe0 simuler et \xe0 pr\xe9dire math\xe9matiquement.\nPar exemple, il est trop co\xfbteux et impraticable de simuler une voiture roulant dans le vent, c'est pourquoi les constructeurs automobiles construisent en r\xe9alit\xe9 des tunnels avec du vent soufflant et font passer des voitures dedans pour tester leurs performances.\nAutrement dit, ils cr\xe9ent du vent au lieu de le simuler.\nConstruire un ordinateur quantique pour \xe9tudier le monde physique, c'est un peu comme construire une soufflerie pour \xe9tudier l'effet du vent sur les voitures.\nLes ordinateurs quantiques peuvent \xe9muler directement les lois de la Nature au niveau mol\xe9culaire parce qu'ils agissent en accord avec ces lois,\nc'est-\xe0-dire qu'ils \xe9mulent la Nature au lieu de la simuler \xe0 travers des formules et des calculs."}),"\n",(0,t.jsxs)(s.p,{children:["D'autres ont fait suite aux id\xe9es de Feynman \u2014 et ils ont li\xe9 ces id\xe9es \xe0 une th\xe9orie de l'",(0,t.jsx)(s.em,{children:"information quantique"})," qui\n\xe9tait d\xe9j\xe0 en cours de d\xe9veloppement.\nLe domaine de l'",(0,t.jsx)(s.em,{children:"information et du calcul quantiques"})," est n\xe9.\nIl s'est depuis d\xe9velopp\xe9 en un riche domaine d'\xe9tude multidisciplinaire, et de nombreux avantages du quantique sur l'information et le calcul classiques ont \xe9t\xe9 identifi\xe9s dans une grande vari\xe9t\xe9 de contextes ",(0,t.jsx)(s.em,{children:"th\xe9oriques"})," impliquant la communication, le calcul et la cryptographie."]}),"\n",(0,t.jsx)(s.h3,{id:"quantum-computing-in-practice",children:"L'informatique quantique en pratique"}),"\n",(0,t.jsx)(s.p,{children:"En termes pratiques, deux choses sont n\xe9cessaires pour transf\xe9rer ce type d'avantages th\xe9oriques en avantages concrets : les dispositifs eux-m\xeames et les m\xe9thodologies pour lib\xe9rer leur potentiel."}),"\n",(0,t.jsx)(s.p,{children:"Contrairement aux ordinateurs classiques, personne n'a un ordinateur quantique dans sa poche.\nJusqu'\xe0 tr\xe8s r\xe9cemment, si tu voulais exp\xe9rimenter avec un ordinateur quantique, tu devais en construire et en entretenir un toi-m\xeame\n(g\xe9n\xe9ralement dans un triste laboratoire de sous-sol d'une universit\xe9 ou d'un \xe9tablissement de recherche), et tu n'aurais eu que quelques qubits tr\xe8s bruit\xe9s au maximum.\nCe n'est plus le cas.\nEn 2016, IBM Quantum\xae a mis le premier processeur quantique sur le cloud.\nIl n'avait que 5 qubits et des taux d'erreurs assez \xe9lev\xe9s, mais on a parcouru beaucoup de chemin depuis.\nNous r\xe9sumerons l'\xe9tat actuel de la technologie dans une section ci-dessous."}),"\n",(0,t.jsx)(s.p,{children:"En plus de construire des ordinateurs quantiques, nous devons aussi d\xe9velopper des m\xe9thodologies pour les utiliser efficacement.\nBien que les avanc\xe9es th\xe9oriques en algorithmes quantiques et en protocoles sugg\xe8rent un fort potentiel, le d\xe9fi de trouver des usages pratiques pour l'informatique quantique est encore devant nous.\nLes ordinateurs quantiques d'aujourd'hui ne peuvent pas encore effectuer les calculs tol\xe9rants aux pannes n\xe9cessaires pour transf\xe9rer les avantages th\xe9oriques connus en avantages pratiques.\nMais ils sont au-del\xe0 de la port\xe9e des simulations d'ordinateurs classiques, et nous pouvons viser \xe0 tirer parti de ce fait pour la puissance computationnelle."}),"\n",(0,t.jsx)(s.p,{children:"Avec ces avanc\xe9es, nous nous retrouvons avec un nouvel outil pour le calcul, et c'est \xe0 nous de d\xe9couvrir ce que nous pouvons en faire."}),"\n",(0,t.jsx)(s.h3,{id:"potential-applications",children:"Applications potentielles"}),"\n",(0,t.jsx)(s.p,{children:"On ne s'attend pas \xe0 ce que l'informatique quantique soit utile pour \xe9tudier comment les voitures se comportent dans le vent.\nMais il existe d'autres processus physiques \u2014 comme ceux impliqu\xe9s dans la conception de batteries ou dans certaines r\xe9actions chimiques \u2014 o\xf9 la capacit\xe9 d'un ordinateur quantique \xe0 \xe9muler la Nature pourrait conduire \xe0 un avantage quantique.\nPlus g\xe9n\xe9ralement, il existe de nombreux probl\xe8mes trop difficiles ou co\xfbteux m\xeame pour les supercalculateurs les plus avanc\xe9s, incluant des probl\xe8mes tr\xe8s pertinents pour notre soci\xe9t\xe9.\nL'informatique quantique ne propose peut-\xeatre pas de solutions \xe0 tous, mais elle pourrait en offrir \xe0 certains."}),"\n",(0,t.jsx)(s.p,{children:"Les trois domaines d'application suivants repr\xe9sentent des cibles dans le domaine du calcul quantique bruit\xe9, avant la mise en \u0153uvre de la correction d'erreurs quantiques et de la tol\xe9rance aux pannes."}),"\n",(0,t.jsxs)(s.ul,{children:["\n",(0,t.jsx)(s.li,{children:"Optimisation"}),"\n",(0,t.jsx)(s.li,{children:"Simulation de la Nature"}),"\n",(0,t.jsx)(s.li,{children:"Recherche de structure dans les donn\xe9es (y compris l'apprentissage automatique)"}),"\n"]}),"\n",(0,t.jsx)(s.p,{children:"Nous aborderons ces sujets plus en d\xe9tail plus tard dans le cours."}),"\n",(0,t.jsx)(s.h3,{id:"state-of-the-technology",children:"\xc9tat de la technologie"}),"\n",(0,t.jsx)(s.p,{children:"Construire des ordinateurs quantiques est un d\xe9fi technologique difficile, et ce n'est que depuis 8 ans que les petits ordinateurs quantiques sont accessibles au public.\nEn ces 8 ans, nous avons progress\xe9 sur de nombreux fronts."}),"\n",(0,t.jsxs)(s.p,{children:["De nombreux processeurs quantiques IBM sont maintenant accessibles via le cloud, et tous ont plus de 100 qubits.\nMais ce n'est pas seulement la taille des processeurs qui importe \u2014 c'est juste une des m\xe9triques qui nous int\xe9ressent.\nLa qualit\xe9 des portes s'est aussi consid\xe9rablement am\xe9lior\xe9e, et nous avons \xe9galement introduit des m\xe9thodes pour r\xe9duire et att\xe9nuer les erreurs intrins\xe8ques aux syst\xe8mes quantiques, m\xeame tandis que nous avan\xe7ons vers la cr\xe9ation de syst\xe8mes tol\xe9rants aux pannes.\nTrois m\xe9triques de base \u2014 ",(0,t.jsx)(s.em,{children:"l'\xe9chelle"}),", ",(0,t.jsx)(s.em,{children:"la qualit\xe9"})," et ",(0,t.jsx)(s.em,{children:"la vitesse"})," \u2014 sont essentielles pour suivre l'am\xe9lioration des performances."]}),"\n",(0,t.jsxs)(s.ul,{children:["\n",(0,t.jsxs)(s.li,{children:["\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.strong,{children:"Taille."})," Plus de qubits, c'est \xe9videmment mieux, mais seulement si l'augmentation du nombre ne d\xe9grade pas les performances\n(ce qui peut \xeatre le cas). En pratique, on veut plus de qubits de bonne qualit\xe9 qui n'interf\xe8rent pas entre eux\nvia du crosstalk quand on ne le souhaite pas. La fa\xe7on dont les qubits sont connect\xe9s les uns aux autres est aussi importante, et\ntrouver la meilleure fa\xe7on de le faire repr\xe9sente un d\xe9fi pour les circuits \xe0 qubits supraconducteurs."]}),"\n"]}),"\n",(0,t.jsxs)(s.li,{children:["\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.strong,{children:"Qualit\xe9."})," Une autre m\xe9trique importante que l'on observe, pour suivre l'am\xe9lioration des performances au fil du temps, est la fid\xe9lit\xe9 des portes \xe0 2 qubits.\nLes portes qui op\xe8rent sur des qubits uniques ne sont pas aussi sujettes aux erreurs que les portes \xe0 2 qubits, qui repr\xe9sentent donc la plus grande pr\xe9occupation.\n(Les portes \xe0 2 qubits sont aussi essentielles car elles sont responsables de la cr\xe9ation de l'intrication entre les qubits, ce qui est\nsuppos\xe9 \xeatre l'un des ph\xe9nom\xe8nes physiques qui donnent \xe0 l'informatique quantique sa puissance.)"]}),"\n"]}),"\n",(0,t.jsxs)(s.li,{children:["\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.strong,{children:"Vitesse."})," Enfin, la vitesse et l'efficacit\xe9. En r\xe9sum\xe9, le temps pass\xe9 \xe0 ex\xe9cuter un programme (incluant les parties quantiques et\nclassiques) doit \xeatre aussi court que possible."]}),"\n"]}),"\n"]}),"\n",(0,t.jsx)(s.h2,{id:"conclusion",children:"Conclusion"}),"\n",(0,t.jsx)(s.p,{children:"C'est vraiment une \xe9poque passionnante pour travailler dans le domaine de l'informatique quantique : pour la premi\xe8re fois dans l'histoire, nous pouvons commencer \xe0 explorer une r\xe9gion du calcul qui se situe au-del\xe0 du calcul classique."}),"\n",(0,t.jsx)(s.p,{children:"T.J. Watson a un jour pr\xe9dit avec c\xe9l\xe8bre qu'il n'y aurait besoin que de quelques ordinateurs dans le monde.\nOn peut en rire maintenant au vu de son erreur \u2014 mais en le faisant, on doit reconna\xeetre que l'on a le b\xe9n\xe9fice du recul.\nEt on doit aussi reconna\xeetre que, en tant qu'humains, nous avons g\xe9n\xe9ralement tendance \xe0 largement sous-estimer le potentiel des technologies futures.\nMaintenant que c'est notre tour et que nous endossons les r\xf4les de pionniers de l'informatique quantique, nous devons garder cela \xe0 l'esprit."}),"\n",(0,t.jsx)(s.p,{children:"L'informatique quantique est souvent mise en contraste avec le calcul classique, comme quelque chose qui lui est distinctement diff\xe9rent et en comp\xe9tition avec lui.\nMais avec un regard plus large, on peut voir l'informatique quantique simplement comme un chapitre de plus dans une longue histoire.\nIl est dans notre nature, en tant qu'humains, de chercher de nouvelles fa\xe7ons de calculer et d'exploiter la puissance que le monde naturel nous offre pour y parvenir.\nNous faisons cela depuis des si\xe8cles.\nL'informatique quantique nous offre un nouvel outil dans cette qu\xeate, et c'est \xe0 nous de d\xe9couvrir comment tirer parti de la puissance qu'elle nous offre."})]})}function d(e={}){const{wrapper:s}={...(0,u.R)(),...e.components};return s?(0,t.jsx)(s,{...e,children:(0,t.jsx)(c,{...e})}):c(e)}},28453(e,s,n){n.d(s,{R:()=>r,x:()=>a});var i=n(96540);const t={},u=i.createContext(t);function r(e){const s=i.useContext(u);return i.useMemo(function(){return"function"==typeof e?e(s):{...s,...e}},[s,e])}function a(e){let s;return s=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:r(e.components),i.createElement(u.Provider,{value:s},e.children)}}}]);